 {% endif %}
 "120910007": { "values": [120910305,120910306], "labels": ["YES","NO"] },
 "120910008": { "values": [120910305,120910306,120910307], "labels": ["YES","NO","N/A"] },
 "120910009": { "values": [120910305,120910306,120910302], "labels": ["YES","NO","INSUFFICIENT EVIDENCE"] },
 "120910010": { "values": [120910300,120910303,120910302,120910304], "labels": ["PASS","PASS WITH ISSUES","INSUFFICIENT EVIDENCE","POTENTIAL HARM"] },
 "120910012": { "values": [120910300,120910303,120910301,120910302,120910307], "labels": ["PASS","PASS WITH ISSUES","POTENTIAL HARM","INSUFFICIENT EVIDENCE","N/A"] }
 },
