 <script>
 (function () {
 'use strict';

 var notice = document.querySelector('[data-ot-checklist-stale]');
 var rows = document.querySelectorAll('[data-ot-answer][data-question-id]');
 if (!notice || !rows.length) { return; }

 var scalesEl = document.querySelector('[data-ot-scales]');
 if (!scalesEl) { return; }
 var SCALES;
 try { SCALES = JSON.parse(scalesEl.textContent); } catch (e) { return; }

 {% comment %}/*
 * The day the server rendered against, so the client cannot disagree with it
 * about what "in force" means because of a time zone.
 */{% endcomment %}
 var AS_OF = '{{ as_of }}';

 var ids = [];
 var seen = {};
 for (var i = 0; i < rows.length; i += 1) {
 var qid = rows[i].getAttribute('data-question-id');
 if (qid && !seen[qid]) { seen[qid] = true; ids.push(qid); }
 }
 if (!ids.length) { return; }

 var clauses = [];
 for (var j = 0; j < ids.length; j += 1) {
 clauses.push('_al_questionid_value eq ' + ids[j]);
 }

 var filter = '(al_effectivefrom eq null or al_effectivefrom le ' + AS_OF + ')'
 + ' and (al_effectiveto eq null or al_effectiveto gt ' + AS_OF + ')'
 + ' and (' + clauses.join(' or ') + ')';

 var url = '/_api/al_questionversions'
 + '?$select=al_questionversionid,_al_questionid_value,al_responsetype,al_questiontext'
 + '&$filter=' + encodeURIComponent(filter);

 var request = new XMLHttpRequest();
 request.open('GET', url, true);
 request.setRequestHeader('Accept', 'application/json');

 request.onreadystatechange = function () {
 if (request.readyState !== 4) { return; }
 if (request.status < 200 || request.status >= 300) { return; }

 var live;
 try { live = JSON.parse(request.responseText).value; } catch (e) { return; }
 if (!live || !live.length) { return; }

 var byQuestion = {};
 for (var k = 0; k < live.length; k += 1) {
 byQuestion[live[k]._al_questionid_value] = live[k];
 }

 apply(byQuestion);
 };

 try { request.send(); } catch (e) { {% comment %}/* offline; the rendered form stands */{% endcomment %} }

 {% comment %}/* The words on a row, so the notice can name what moved rather than count it. */{% endcomment %}
 function labelOf(row) {
 var cell = row.querySelector('td.label, td.lbl');
 if (!cell) { return 'A question'; }
 var text = cell.cloneNode(true);
 var marks = text.querySelectorAll('.ot-required, .ot-answer__status');
 for (var i = 0; i < marks.length; i += 1) {
 marks[i].parentNode.removeChild(marks[i]);
 }
 return (text.textContent || '').replace(/^\s+|\s+$/g, '');
 }

 function apply(byQuestion) {
 var moved = [];
 var cleared = 0;

 for (var i = 0; i < rows.length; i += 1) {
 var row = rows[i];
 var current = byQuestion[row.getAttribute('data-question-id')];
 if (!current) { continue; }

 var renderedVersion = row.getAttribute('data-question-version');
 if (current.al_questionversionid === renderedVersion) { continue; }

 var was = labelOf(row);
 var renderedType = Number(row.getAttribute('data-response-type'));
 var liveType = Number(current.al_responsetype);

 {% comment %}/*
 * The row now answers a different version, whatever else changed: point the
 * autosave at it before anything else, so a save made a moment later is
 * written against the version the server will accept.
 */{% endcomment %}
 row.setAttribute('data-question-version', current.al_questionversionid);
 row.setAttribute('data-response-type', String(liveType));

 retext(row, current.al_questiontext);

 {% comment %}/*
 * And the text the remedial-actions card keys this row's item by. The server
 * names the item by the version in force, so a card still keyed by the old
 * wording would have the submit refused naming a row it does not show. Blank
 * where the successor has no wording, which the server skips as well.
 */{% endcomment %}
 row.setAttribute('data-question-text', current.al_questiontext || '');

 if (liveType !== renderedType) {
 if (rebuild(row, liveType, current)) { cleared += 1; }
 }

 moved.push(was);
 }

 if (!moved.length) { return; }

 reheadGrids();
 announce(moved, cleared);

 {% comment %}// Nothing above fires a change event - a re-keyed row, or a tick rebuild()
 // dropped - so the card is told directly. Absent on a read-only review.{% endcomment %}
 if (window.otRemedial && typeof window.otRemedial.redraw === 'function') { window.otRemedial.redraw(); }
 }

 {% comment %}/*
 * The question's own wording, replaced without disturbing the Required marker or
 * the live status span the autosave writes into.
 */{% endcomment %}
 function retext(row, wording) {
 if (!wording) { return; }
 var cell = row.querySelector('td.label, td.lbl');
 if (!cell) { return; }
 for (var i = 0; i < cell.childNodes.length; i += 1) {
 if (cell.childNodes[i].nodeType === 3) {
 cell.childNodes[i].nodeValue = wording;
 return;
 }
 }
 }

 {% comment %}/*
 * The answer options, redrawn from the live scale. Returns true when a tick was
 * dropped because the new scale has no such value - the one consequence a
 * checker has to be told about.
 */{% endcomment %}
 function rebuild(row, liveType, current) {
 var opts = row.querySelector('.opts');
 var scale = SCALES.inline[String(liveType)];
 if (!opts || !scale) { return false; }

 var chosen = opts.querySelector('input[type="radio"]:checked');
 var chosenValue = chosen ? chosen.value : null;

 {% comment %}/*
 * WHICH options were locked, one by one - not WHETHER any of them was.
 *
 * This read querySelector('[disabled]') into a single flag and applied that
 * flag to every option it then rebuilt. That was right for as long as a lock
 * was all or nothing: a read-only form disabled the row entire. From
 * 2026-09-23 to 2026-10-05 the grading rules (since withdrawn - project owner:
 * "allow any answer") disabled a SINGLE option and left the rest live - Pass
 * taken away by a finding, Yes taken away by a file quality Pass - so
 * collapsing it to one flag re-drew the row with EVERY option dead, and a
 * checker whose checklist was reissued mid-answer could no longer answer the
 * question at all. OT Answer Options' own `locked` param can still disable one
 * option without the rest for any other reason a caller has, so the per-option
 * read stays the honest one.
 *
 * Read-only still holds, because it is the same rule read honestly: a row
 * where every option was locked sets allLocked, and any option the new scale
 * ADDS is locked with it rather than arriving live on a form nobody may edit.
 */{% endcomment %}
 var priorInputs = opts.querySelectorAll('input[type="radio"]');
 var lockedValues = '|';
 var lockedCount = 0;
 for (var d = 0; d < priorInputs.length; d += 1) {
 if (!priorInputs[d].disabled) { continue; }
 lockedValues += priorInputs[d].value + '|';
 lockedCount += 1;
 }
 var allLocked = priorInputs.length > 0 && lockedCount === priorInputs.length;

 var keeps = false;
 for (var i = 0; i < scale.values.length; i += 1) {
 if (String(scale.values[i]) === chosenValue) { keeps = true; }
 }

 var wording = current.al_questiontext || labelOf(row);
 while (opts.firstChild) { opts.removeChild(opts.firstChild); }

 for (var v = 0; v < scale.values.length; v += 1) {
 var value = String(scale.values[v]);
 var label = document.createElement('label');
 label.className = 'opt';
 var input = document.createElement('input');
 input.type = 'radio';
 input.className = 'cc-box';
 input.name = 'q-' + current.al_questionversionid;
 input.value = value;
 input.setAttribute('data-ot-input', '');
 input.setAttribute('aria-label', wording + ': ' + scale.labels[v]);
 if (allLocked || lockedValues.indexOf('|' + value + '|') !== -1) {
 input.disabled = true;
 label.className = 'opt opt--locked';
 }
 if (keeps && value === chosenValue) { input.checked = true; }
 label.appendChild(input);
 label.appendChild(document.createTextNode(' ' + scale.labels[v]));
 opts.appendChild(label);
 }

 return chosenValue !== null && !keeps;
 }

 {% comment %}/*
 * A tick grid heads its columns from the scale its rows answer on. Re-headed only
 * where every row in the table now agrees, which is the same test the server
 * makes: a table whose rows disagree has no honest column heading, and leaving
 * the old one is better than inventing one.
 */{% endcomment %}
 function reheadGrids() {
 var grids = document.querySelectorAll('table.grid');
 for (var g = 0; g < grids.length; g += 1) {
 var gridRows = grids[g].querySelectorAll('[data-ot-answer][data-response-type]');
