 var CACHE_LAG_KEY = 'ot.savedAnswers.' + REVIEW_ID;
 var CACHE_LAG_WINDOW_MS = 20 * 60 * 1000;
 var cacheLagProbes = {};

 function readSavedAnswers() {
 try { return JSON.parse(window.sessionStorage.getItem(CACHE_LAG_KEY) || '{}') || {}; }
