 function isBlankRequest(request) {
 return request.answerText === null
 && request.answerRichText === null
 && request.answerChoice === null
 && request.answerDate === null
 && (!request.answerChoices || request.answerChoices.length === 0)
 && (!request.failReasons || request.failReasons.length === 0);
 }

 function bind(root) {
 var questionVersion = root.getAttribute('data-question-version');
 var column = root.getAttribute('data-column');
 var status = root.querySelector('[data-ot-status]');
 {% comment %}// The standalone fail points list (AD-096) belongs to the File quality outcome
 // answer, so only that answer's bind() finds one; every other answer has none.{% endcomment %}
