 function done() {
 var now = new Date();
 {% comment %}// An answer just saved is no longer one the submit refused for.{% endcomment %}
 root.classList.remove('ot-answer--missing');
 show('Saved ' + two(now.getHours()) + ':' + two(now.getMinutes()), 'saved');

 {% comment %}// CACHE_LAG: what this tab knows it has saved. Clearing an answer is
 // recorded as nothing to catch up on, so blanking a value never raises
 // the notice.{% endcomment %}
