 {% comment %}// Clear empties the answer. It used to be removeFormat, which only unbolds a
 // selection: with the caret merely in the field it did nothing, and the text a
 // checker meant to clear stayed. selectAll + delete rather than innerHTML = '' so
 // Ctrl+Z brings the text back after a mis-press. currentPayload() sends an editor
 // with no words as null, and AnswerWriter stores that as cleared.{% endcomment %}
 var clear = root.querySelector('[data-ot-rte-clear]');
 if (clear) {
 clear.addEventListener('mousedown', function (event) {
 event.preventDefault();
 area.focus();
 try {
 document.execCommand('selectAll', false, null);
 document.execCommand('delete', false, null);
 } catch (e) {
 area.innerHTML = '';
 }
 queue();
 });
 }

 {% comment %}// A paste arrives as whatever the source page was. Taking the plain text
 // keeps a paste from Word or a web page out of an answer that would only be
 // stripped back to words on the way in anyway.{% endcomment %}
 area.addEventListener('paste', function (event) {
 var clip = event.clipboardData || window.clipboardData;
 if (!clip) { return; }
 event.preventDefault();
 document.execCommand('insertText', false, clip.getData('text/plain') || '');
 queue();
 });
 }

 {% comment %}// No closure over the box is needed any more: toggleReason() no longer takes
 // one, since a tick is just another field feeding queue() -> save().{% endcomment %}
 var reasonBoxes = reasons ? reasons.querySelectorAll('[data-ot-reason]') : [];
 for (var r = 0; r < reasonBoxes.length; r++) {
 reasonBoxes[r].addEventListener('change', toggleReason);
 }

 {% comment %}// CACHE_LAG: how this answer reports whether the page came back empty for it.{% endcomment %}
 cacheLagProbes[questionVersion] = function () {
 return isBlankRequest(currentRequest());
 };
 }

 var answers = document.querySelectorAll('[data-ot-answer]');
 for (var i = 0; i < answers.length; i++) { bind(answers[i]); }

 {% comment %}/*
 * CACHE_LAG, the read side. Runs once, after every answer has bound and
 * registered how to read itself. An answer counts as behind when this tab saved
 * it recently and the page has come back with nothing in it - never when the page
 * shows something, so a value the server did send is never contradicted.
 */{% endcomment %}
 (function reportCacheLag() {
 var saved = readSavedAnswers();
 var now = Date.now();
 var stillFresh = {};
 var behind = 0;
 var qv;
 var isBlankNow;

 for (qv in saved) {
 if (!Object.prototype.hasOwnProperty.call(saved, qv)) { continue; }
