 var notice = document.querySelector('[data-ot-cache-notice]');
 if (!notice || behind === 0) { return; }

 var one = behind === 1;
 var they = one ? 'It is' : 'They are';
 var them = one ? 'it' : 'them';
 var theyWill = one ? 'it will' : 'they will';

 notice.innerHTML = '';
 var strong = document.createElement('strong');
 strong.textContent = one
 ? 'One answer you saved is not shown below yet.'
 : behind + ' answers you saved are not shown below yet.';
 notice.appendChild(strong);
 notice.appendChild(document.createTextNode(
 ' ' + they + ' saved. This site caches pages for up to fifteen minutes, so a '
 + 'reload can arrive before the page catches up. Do not enter ' + them
 + ' again: reload in a few minutes and ' + theyWill + ' be there. Submitting '
 + 'is checked against what is stored, not against what is on screen.'));
