 </thead>
 <tbody data-ot-remedial-parked-rows></tbody>
 </table>
 </div>
 <script>
 (function () {
 var root = document.querySelector('[data-ot-remedial-parked]');
 var body = root.querySelector('[data-ot-remedial-parked-rows]');
 var entries = [];
 try { entries = JSON.parse(root.getAttribute('data-ot-remedial-parked')) || []; } catch (e) { entries = []; }
 entries.forEach(function (entry, index) {
 var row = body.insertRow();
 row.insertCell().textContent = String(index + 1);
 row.insertCell().textContent = entry.item === '__overall__' ? '—' : entry.item;
 var words = row.insertCell();
 words.textContent = entry.text;
 words.style.whiteSpace = 'pre-line';
 });
